import re


def render(template, context):
    def value(m):
        node = context
        for key in m.group(1).split("."):
            if not isinstance(node, dict) or key not in node:
                return ""
            node = node[key]
        return str(node)
    return re.sub(r"\$\{\{\s*([\w.-]+)\s*\}\}", value, template)

