from fnmatch import fnmatch


def env_ignored(gitignore):
    ignored = False
    for line in gitignore.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        negate = line.startswith("!")
        pattern = line.lstrip("!").lstrip("/")
        if fnmatch(".env", pattern):
            ignored = not negate
    return ignored

