exercises.solution:
def trend(history, current):
    runs = history + [current]
    start = max(0, len(runs) - 5)
    return [f"{i + 1} " + "█" * (r["passed"] // 10) + "░" * (r["failed"] // 10)
            for i, r in enumerate(runs) if i >= start]

